 edit("layers.set_material",{{"reference",fill},{"resource",material.id.toString()}});assert(info(fill)["source_mode"]=="material");edit("layers.set_source",{{"reference",fill},{"channel",2},{"source",.7}});assert(info(fill)["source_mode"]=="split");
